// ─────────────────────────────────────
// VERS ET DU JOUR — HEURE FRANÇAISE
// ─────────────────────────────────────
function getDateFrance() {
  const maintenant = new Date();
  const parties = new Intl.DateTimeFormat("fr-FR", {
    timeZone: "Europe/Paris",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(maintenant);
  return {
    annee: Number(parties.find(p => p.type === "year").value),
    mois: Number(parties.find(p => p.type === "month").value),
    jour: Number(parties.find(p => p.type === "day").value)
  };
}
function getNumeroJour() {
  const date = getDateFrance();
  return date.annee * 10000 + date.mois * 100 + date.jour;
}
function afficherVersetDuJour() {
  const index = getNumeroJour() % versets.length;
  const verset = versets[index];
  document.getElementById("verset-texte").textContent = verset.texte;
  document.getElementById("verset-ref").textContent = verset.ref;
}
// ─────────────────────────────────────
// BOUTON : VERSET DU JOUR (affichage uniquement au clic)
// ─────────────────────────────────────
document.getElementById("verset-jour").addEventListener("click", function () {
  afficherVersetDuJour();
});
// ─────────────────────────────────────
// BOUTON : TIRAGE ALÉATOIRE
// ─────────────────────────────────────
document.getElementById("tirer-verset").addEventListener("click", function () {
  const choix = versets[Math.floor(Math.random() * versets.length)];
  document.getElementById("verset-texte").textContent = choix.texte;
  document.getElementById("verset-ref").textContent = choix.ref;
});
